-- MI-19 Guest service journey, ancillary and reputation provider contracts.
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_guest_request(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),property_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,stay_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest_stay(id) ON DELETE RESTRICT,guest_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest(id) ON DELETE RESTRICT,request_type VARCHAR(32) NOT NULL,description TEXT NOT NULL,priority VARCHAR(12) NOT NULL DEFAULT 'NORMAL',status VARCHAR(16) NOT NULL DEFAULT 'OPEN',assigned_to UUID,due_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,source VARCHAR(20) NOT NULL DEFAULT 'STAFF',idempotency_key VARCHAR(128) UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT ck_hospitality_guest_request_status CHECK(status IN('OPEN','ASSIGNED','IN_PROGRESS','COMPLETED','CANCELLED')),CONSTRAINT ck_hospitality_guest_request_priority CHECK(priority IN('LOW','NORMAL','HIGH','URGENT')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_ancillary_booking(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),property_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,stay_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest_stay(id) ON DELETE RESTRICT,service_type VARCHAR(20) NOT NULL,provider_reference VARCHAR(160),scheduled_at TIMESTAMPTZ NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'REQUESTED',quantity INTEGER NOT NULL DEFAULT 1,amount NUMERIC(16,2) NOT NULL DEFAULT 0,details JSONB NOT NULL DEFAULT '{}'::jsonb,folio_transaction_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_folio_transaction(id) ON DELETE RESTRICT,idempotency_key VARCHAR(128) NOT NULL UNIQUE,CONSTRAINT ck_hospitality_ancillary_type CHECK(service_type IN('CONCIERGE','TRANSPORT','PARKING','ACTIVITY','SPA','PARCEL','VISITOR')),CONSTRAINT ck_hospitality_ancillary_status CHECK(status IN('REQUESTED','CONFIRMED','IN_PROGRESS','COMPLETED','CANCELLED')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_guest_communication(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),guest_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest(id) ON DELETE RESTRICT,stay_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest_stay(id) ON DELETE RESTRICT,journey_stage VARCHAR(12) NOT NULL,channel VARCHAR(16) NOT NULL,template_code VARCHAR(64),content TEXT NOT NULL,consent_basis VARCHAR(32),status VARCHAR(16) NOT NULL DEFAULT 'DRAFT',provider_reference VARCHAR(180),scheduled_at TIMESTAMPTZ,sent_at TIMESTAMPTZ,created_by UUID,CONSTRAINT ck_hospitality_comm_stage CHECK(journey_stage IN('PRE_STAY','IN_STAY','POST_STAY')),CONSTRAINT ck_hospitality_comm_status CHECK(status IN('DRAFT','QUEUED','SENT','FAILED','CANCELLED')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_feedback(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),property_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,guest_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest(id) ON DELETE RESTRICT,stay_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_guest_stay(id) ON DELETE RESTRICT,rating INTEGER NOT NULL,comment TEXT,source VARCHAR(24) NOT NULL DEFAULT 'DIRECT',external_reference VARCHAR(180),status VARCHAR(16) NOT NULL DEFAULT 'NEW',response_draft TEXT,response_approved_by UUID,response_sent_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT ck_hospitality_feedback_rating CHECK(rating BETWEEN 1 AND 5),CONSTRAINT ck_hospitality_feedback_status CHECK(status IN('NEW','REVIEWED','RESPONDED','CLOSED')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_reputation_provider(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),property_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,provider_key VARCHAR(64) NOT NULL,credential_reference VARCHAR(180),status VARCHAR(24) NOT NULL DEFAULT 'BLOCKED_PROVIDER_INPUT',last_sync_at TIMESTAMPTZ,UNIQUE(property_id,provider_key));
CREATE INDEX IF NOT EXISTS ix_hospitality_guest_request_board ON "{{TENANT_SCHEMA}}".hospitality_guest_request(property_id,status,due_at);
